def test_main_pool_defined_exactly_once_in_source():
    """RED at HEAD (appears twice), GREEN after the dedup refactor."""
    src = _read_source()
    occurrences = src.count('def main_pool():')
    assert occurrences == 1, f"Expected exactly one textual 'def main_pool():' in harness/sandbox.py after the dedup refactor, found {occurrences}."

def test_main_pool_template_constant_defined_exactly_once():
    """RED at HEAD (constant absent), GREEN after the refactor introduces it."""
    src = _read_source()
    tree = ast.parse(src)
    count = 0
    for node in tree.body:
        targets = []
        if isinstance(node, ast.Assign):
            targets = list(node.targets)
        elif isinstance(node, ast.AnnAssign):
            targets = [node.target]
        for target in targets:
            if isinstance(target, ast.Name) and target.id == '_MAIN_POOL_TEMPLATE':
                count += 1
    assert count == 1, f"Expected exactly one module-level '_MAIN_POOL_TEMPLATE = ...' assignment in harness/sandbox.py, found {count}."

def test_runner_template_equals_golden_head_bytes():
    """_RUNNER_TEMPLATE must stay byte-for-byte equal to the pinned HEAD value."""
    assert sandbox._RUNNER_TEMPLATE == GOLDEN_RUNNER_TEMPLATE

def test_batch_runner_template_equals_golden_head_bytes():
    """_BATCH_RUNNER_TEMPLATE must stay byte-for-byte equal to the pinned HEAD value."""
    assert sandbox._BATCH_RUNNER_TEMPLATE == GOLDEN_BATCH_RUNNER_TEMPLATE

def test_both_templates_compile():
    """Each emitted runner template must remain valid, compilable Python."""
    compile(sandbox._RUNNER_TEMPLATE, '<runner>', 'exec')
    compile(sandbox._BATCH_RUNNER_TEMPLATE, '<runner>', 'exec')

@requires_fork
def test_pool_path_executes_both_runners_with_identical_results(tmp_path):
    """Run the trivial identity function through the runner emitted from
    ``_RUNNER_TEMPLATE`` (working single path) and the runner emitted from
    ``_BATCH_RUNNER_TEMPLATE`` (real persistent pool path), and assert both run
    and return identical, correct results.
    """
    inputs = [{'args': [42], 'kwargs': {}}]
    single_cfg = sandbox.SandboxConfig(filesystem_root=str(tmp_path / 'single_root'), timeout_per_input_ms=5000, seccomp=False)
    sb = sandbox.Sandbox(config=single_cfg, session_id='oracle_single')
    try:
        single_res = sb.execute(_IDENTITY_CODE, 'identity', [42])
    finally:
        sb.cleanup()
    pool_cfg = sandbox.SandboxConfig(filesystem_root=str(tmp_path / 'pool_root'), timeout_per_input_ms=5000, seccomp=False)
    pool = sandbox.BatchWorkerPool(size=1, config=pool_cfg, session_id='oracle_pool')
    try:
        pool_batch = pool.submit(_IDENTITY_CODE, 'identity', inputs)
    finally:
        pool.shutdown()
    assert pool_batch.batch_error is None, pool_batch.batch_error
    assert len(pool_batch.results) == 1
    pool_res = pool_batch.results[0]
    assert single_res.success is True, single_res.exception_message
    assert single_res.return_value == 42
    assert pool_res.success is True, pool_res.exception_message
    assert pool_res.return_value == 42
    assert single_res.success == pool_res.success
    assert single_res.return_value == pool_res.return_value

@requires_fork
def test_batch_runner_template_smoke_still_passes(tmp_path):
    """BatchRunner.execute_batch (the _BATCH_RUNNER_TEMPLATE single path) still
    runs a trivial submission correctly."""
    cfg = sandbox.SandboxConfig(filesystem_root=str(tmp_path / 'batch_root'), timeout_per_input_ms=5000, seccomp=False)
    br = sandbox.BatchRunner(config=cfg, session_id='oracle_batch')
    try:
        batch = br.execute_batch(_IDENTITY_CODE, 'identity', [{'args': [7], 'kwargs': {}}])
    finally:
        br.cleanup()
    assert batch.batch_error is None, batch.batch_error
    assert batch.total_inputs == 1
    assert batch.results[0].success is True, batch.results[0].exception_message
    assert batch.results[0].return_value == 7

@requires_fork
def test_diff_fuzzer_pool_smoke_still_passes(tmp_path):
    """The diff-fuzzer pool path (BatchWorkerPool.submit) still runs a trivial
    submission correctly."""
    cfg = sandbox.SandboxConfig(filesystem_root=str(tmp_path / 'fuzzpool_root'), timeout_per_input_ms=5000, seccomp=False)
    pool = sandbox.BatchWorkerPool(size=1, config=cfg, session_id='oracle_fuzzpool')
    try:
        batch = pool.submit(_IDENTITY_CODE, 'identity', [{'args': [99], 'kwargs': {}}])
    finally:
        pool.shutdown()
    assert batch.batch_error is None, batch.batch_error
    assert batch.total_inputs == 1
    assert batch.results[0].success is True, batch.results[0].exception_message
    assert batch.results[0].return_value == 99